 public void onInitializeClient(){try{modern=System.getProperty("pack.version").startsWith("26.");Class<?> events=Class.forName("net.fabricmc.fabric.api.client.event.lifecycle.v1.ClientTickEvents");Object event=events.getField("END_CLIENT_TICK").get(null);Class<?> listener=Class.forName(events.getName()+"$EndTick");Object proxy=Proxy.newProxyInstance(listener.getClassLoader(),new Class<?>[]{listener},(p,m,a)->{if(m.getDeclaringClass()==Object.class){if(m.getName().equals("hashCode"))return System.identityHashCode(p);if(m.getName().equals("toString"))return "PackStudioTest";return p==a[0];}tick(a[0]);return null;});Class.forName("net.fabricmc.fabric.api.event.Event").getMethod("register",Object.class).invoke(event,proxy);}catch(Throwable t){fail(t);}}
